style.css:
@-moz-document domain("pinterest.com") {
/* 1. Set your custom skull artwork with absolute clarity */
    body, 
    #initial-focus-wrapper, 
    div[data-test-id="main-container"] {
        background-image: url('https://i.imgur.com/YkyKqBh.jpeg') !important;
        background-size: cover !important;
        background-repeat: no-repeat !important;
        background-attachment: fixed !important;
        background-position: center !important;
        filter: none !important; /* Disables any global filter blurring */
    }

    /* 2. Ghostly Grey Panels - Completely Unblurred */
    div[role="main"],
    .Grid,
    div[data-test-id="board-header"],
    div[data-test-id="pin"],
    div[data-test-id="pin-save-dropdown"] {
        background-color: rgba(45, 48, 56, 0.25) !important; /* Low-opacity slate grey lets artwork pierce through */
        backdrop-filter: none !important; /* Completely stripped out so background is 100% sharp */
        border-radius: 16px !important;
        border: 1px solid rgba(255, 255, 255, 0.05) !important; /* Micro-thin border line to define shapes */
    }

    /* 3. Matte Black Top Search Bar & Main Header */
    header[role="banner"],
    header[role="banner"] > div,
    div[data-test-id="search-box-input"],
    form[name="search"] input {
        background-color: #050505 !important; /* Pure ink black */
        color: #ffffff !important; 
        border: none !important;
    }

    /* 4. Deep Black Side Interfaces & Floating Dropdowns */
    div[role="navigation"],
    div[data-test-id="sidebar"],
    div[role="menu"],
    div[data-test-id="search-flyout"],
    #guided-help-container,
    div[role="dialog"] {
        background-color: #050505 !important;
        border-radius: 12px !important;
        border: 1px solid #151515 !important;
    }

    /* 5. High-Contrast White Text to Beat the Black Background Shadows */
    h1, h2, h3, p, span, div, a, .tread-muted, div[color="subtle"] {
        color: #ffffff !important;
        text-shadow: 2px 2px 4px rgba(0, 0, 0, 1), -1px -1px 2px rgba(0, 0, 0, 1) !important; /* Bold drop outline shadow */
    }

    /* 6. Muted Gray Search Bar Placeholder */
    form[name="search"] input::placeholder {
        color: #757575 !important;
    }

    /* 7. Header Navigation Icons Keep Bright White Finish */
    header[role="banner"] svg {
        color: #ffffff !important;
    }
}
